-- Starter ingredients & recipe (Shakshuka Miam's). Costs are estimates; receiving updates them automatically.
on conflict do nothing;
select mi.id, i.id, v.qty, v.y from (values
  ('Œuf gros (Québec)', 2, 100), ('Sauce shakshuka (maison)', 280, 100), ('Feta', 30, 100), ('Pain au levain', 90, 95), ('Coriandre fraîche', 4, 80)
) v(name, qty, y) join ingredients i on i.name = v.name and i.org_id = '00000000-0000-0000-0000-00000000000a'
join menu_items mi on mi.slug = 'shakshuka' and mi.org_id = '00000000-0000-0000-0000-00000000000a';
select '00000000-0000-0000-0000-0000000000b1', id, case unit when 'unit' then 360 else 20000 end, case unit when 'unit' then 360 else 20000 end, case unit when 'unit' then 90 else 5000 end
from ingredients where org_id = '00000000-0000-0000-0000-00000000000a' on conflict do nothing;


